22	/**
23	 * Du nouveau (activité Claude) depuis la dernière lecture de Franck.
24	 * `false` pour un document jamais ouvert : ce cas est couvert séparément par
25	 * `isNeverOpened` — ne pas doubler le badge « jamais ouvert » avec un badge
26	 * « nouveau » sur le même document.
27	 */
28	export function hasNewActivitySinceRead(doc: UnreadFields): boolean {
29	  if (!doc.lastActivityAt) return false;
30	  if (!doc.lastReadAt) return false;
