2	 * Persistance de l'état de vue (filtres, onglets, recherche, tri, replis…) —
3	 * logique PURE, sans dépendance React ni accès direct à `window`.
4	 *
5	 * Trois niveaux (voir docs du chantier persistance-filtres-onglets-ui) :
6	 *   - `storage: 'url'`     → URL search params (routable, partageable), avec
7	 *                            une copie en `sessionStorage` comme filet.
8	 *   - `storage: 'session'` → `sessionStorage` seul (états verbeux/ergonomiques,
9	 *                            ex. `collapsedProjects: Record<string, boolean>`).
10	 *   - localStorage (préférences durables) est hors périmètre de ce module.
11	 *
12	 * Précédence par clé, au montage : URL > sessionStorage > défaut. Toute
13	 * valeur restaurée est validée ; une valeur invalide (ou un storage qui jette,
14	 * ex. navigation privée stricte) ne provoque jamais d'exception — elle
15	 * dégrade silencieusement vers la clé de repli suivante, puis vers le défaut.
16	 *
17	 * Le storage (session) est injecté en paramètre — jamais `window.sessionStorage`
18	 * en dur ici — pour rester testable sans DOM (cf. le style try/catch de
19	 * `src/components/NotificationCenter.tsx` / `src/hooks/useDesktopNotifications.ts`).
20	 */
21	
22	/** Sous-ensemble de `Storage` (DOM) suffisant pour l'injection en test. */
23	export interface ViewStateStorage {
24	  getItem(key: string): string | null;
25	  setItem(key: string, value: string): void;
26	}
27	
28	/**
29	 * Valide une valeur candidate (déjà parsée) : soit une liste d'énum, soit un
30	 * prédicat borné. Reçoit `unknown` — la valeur peut venir d'une URL ou d'un
31	 * JSON.parse de sessionStorage, donc jamais garantie du bon type a priori.
32	 */
33	export type ViewStateValidate<V> = readonly V[] | ((value: unknown) => boolean);
34	
35	export interface ViewStateFieldSpec<V> {
36	  /**
37	   * Nom de la clé dans l'URL (`storage: 'url'`) ou dans le sessionStorage
38	   * (`storage: 'session'`). Par défaut : le nom de la clé de la spec.
39	   */
40	  urlKey?: string;
41	  storage: 'url' | 'session';
42	  default: V;
43	  validate: ViewStateValidate<V>;
44	  /** `storage: 'url'` uniquement : parse la chaîne brute du search param. */
45	  parse?: (raw: string) => unknown;
46	  /** `storage: 'url'` uniquement : sérialise la valeur en chaîne pour l'URL. */
47	  serialize?: (value: V) => string;
48	}
49	
50	export type ViewStateSpec<T extends Record<string, unknown>> = {
51	  [K in keyof T]: ViewStateFieldSpec<T[K]>;
52	};
53	
54	function isValidValue<V>(validate: ViewStateValidate<V>, value: unknown): value is V {
55	  if (Array.isArray(validate)) return (validate as readonly unknown[]).includes(value);
56	  return (validate as (value: unknown) => boolean)(value);
57	}
58	
59	function defaultParse(raw: string, defaultValue: unknown): unknown {
60	  if (typeof defaultValue === 'number') {
61	    const parsed = Number(raw);
62	    return Number.isNaN(parsed) ? raw : parsed;
63	  }
64	  if (typeof defaultValue === 'boolean') {
65	    if (raw === 'true') return true;
66	    if (raw === 'false') return false;
67	    return raw;
68	  }
69	  return raw;
70	}
